// Grab the text output from the AI Agent
let text = $input.item.json.output || $input.item.json.text || "";

// Look for the hidden data block
const regex = /<CHART_DATA>\s*({[\s\S]*?})\s*<\/CHART_DATA>/;
const match = text.match(regex);

if (match && match[1]) {
    try {
        const data = JSON.parse(match[1]);
        const labels = data.labels || [];
        const values = data.values || [];

        // Build the strict Chart.js schema
        const chartConfig = {
            type: 'line',
            data: {
                labels: labels,
                datasets: [{
                    label: 'Net Cost ($B)',
                    data: values,
                    backgroundColor: 'rgba(54, 162, 235, 0.2)',
                    borderColor: 'rgba(54, 162, 235, 1)',
                    borderWidth: 2,
                    fill: true
                }]
            },
            options: {
                responsive: true,
                plugins: {
                    title: { display: true, text: 'Department of Energy Net Cost Trend' },
                    legend: { display: false }
                }
            }
        };

        // Fully URL-encode the configuration
        const encoded = encodeURIComponent(JSON.stringify(chartConfig));
        const url = `https://quickchart.io/chart?c=${encoded}&w=700&h=350&bkg=white`;

        const markdownImage = `\n\n## Visual Representation\n![Net Cost Trend](${url})\n\n`;

        // Replace the hidden data block with the actual Markdown image
        text = text.replace(regex, markdownImage);

    } catch (e) {
        // Fallback if parsing fails
    }
}

// Return the final formatted text back to the chat interface
return {
    json: {
        output: text
    }
};
